// Rorschach living cells
//
// Created by Nicolas Decoster for the
// topic "Symmetries 🪞" of #WCCChallenge


var params = {
	size: 600,
	speed: 0.005,
	scale: 0.008,
	maxRadius: 8,
}

var offsets = {
	x: params.size/2,
	y: params.size * 7/6,
}

var min = (a, b) => a < b ? a : b

// Get plotter characteristics from a value in [0, 1] intervall.
//
// For the plotter color, an array of colors is equally mapped
// between 0 and 1.
// 
// The plotter radius start from zero and increase to its maximum
// at the middle of the color range of values. And decreases after
// that to zero again. The idea is to have smaller plotters at
// color trransitions.
//
// Call drawPlottersPalette() to see a mapping of plotters for
// values from 0 to 1.
function getPlotter(value) {
	const white = color(255, 255, 255)
	const alpha = 150
	const black = color(0, 0, 0, alpha)
	const blue = color(28, 69, 113, alpha)
	const red = color(235, 23, 25, alpha)
	const colors = [
		white,
		white,
		red,
		white,
		blue,
		white,
		black,
		white,
		white,
	]

	const n = colors.length
	// Size of an intervall.
	const size = 1 / n
	// Corresponding color index for the current value.
	const index = Math.floor(value/size)
	// Corresponding [0,1] in the current color intervall.
	// I.e. if there are 2 colors, and value is 0.6, this will
	// be 0.2. I.e size is 0.5, and 0.6 is at 20 % of the current
	// function intervall(last color).
	const valueInIntervall = (value - (index * size))/size

	// To get the radius, with fading ones on color transition.
	const center = 0.5
	const radiusScale =
				2 * (center - Math.abs(valueInIntervall - center))

	return {
		color: colors[index],
		radius: params.maxRadius * radiusScale
	}
}

// This will draw all plotters for values from 0 to 1, to see what
// they all look like.
function drawPlottersPalette() {
	var n = 100
	for (let i = 0; i < n; i++) {
		const plotter = getPlotter(i/n)
		fill(plotter.color)
		noStroke()
		const step = 5
		circle(
			50 + i*step,
			50,
			plotter.radius
		)
	}
}

// Apply some white shadowing on each frame to fade out previous
// drawned cells.
function fadeOut() {
	fill(255, 10)
	noStroke()
	rect(0, 0, width, height)
}

function rotatePlotter(x0, y0, angle) {
	const cos = Math.cos(angle)
	const sin = Math.sin(angle)
	const x = x0 * cos - y0 * sin
	const y = x0 * sin + y0 * cos
	return [x, y]	
}


// *********************************************************

function setup() {
	createCanvas(windowWidth, windowHeight); params.size = min(width, height); offsets.x = width / 2; offsets.y = height * 7/6;
	// Comment to randomize the plot
	noiseSeed(7821)
}

function draw() {
	fadeOut()

	// Uncomment the following to see the plotters palette at the
	// top of the canvas.
	// drawPlottersPalette()

	const nPlotters = 2000
	for (let i = 0; i < nPlotters; i++) {
		const a = Math.random() * 100
		const b = Math.random() * 100

		// Esoteric way to get x and y. I don't remember why I did
		// this, but, it still seems better looking to me than pure
		// random. So, keep it.
		const x0 = noise(a, b) * params.size;
		const y0 = noise(b, a) * params.size;

		// The is symmetrical about the diagonal. Rotate
		// eveything to make it symmetrical about the y axis.
		const [x, y] = rotatePlotter(x0, y0, - 3 * PI / 4)

		// Get plotter properties randommly based on its position
		// in the plane. In fact, these two lines is the part that
		// has the most impact in the final rendering.
		const val = noise(
			x * params.scale,
			y * params.scale,
			frameCount * params.speed
		)
		var plotter = getPlotter(val)

		// Actually plot the dot
		fill(plotter.color)
		noStroke()
		circle(
			x + offsets.x,
			y + offsets.y,
			plotter.radius
		)		
	}
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  params.size = min(width, height);
  offsets.x = width / 2;
  offsets.y = height * 7/6;
}


